1	package com.bumptech.glide.load.engine;
2	
3	import androidx.annotation.GuardedBy;
4	import androidx.annotation.NonNull;
5	import androidx.annotation.VisibleForTesting;
6	import androidx.core.util.Pools;
7	import com.bumptech.glide.load.DataSource;
8	import com.bumptech.glide.load.Key;
9	import com.bumptech.glide.load.engine.EngineResource.ResourceListener;
10	import com.bumptech.glide.load.engine.executor.GlideExecutor;
11	import com.bumptech.glide.request.ResourceCallback;
12	import com.bumptech.glide.util.Executors;
13	import com.bumptech.glide.util.Preconditions;
14	import com.bumptech.glide.util.Synthetic;
15	import com.bumptech.glide.util.pool.FactoryPools.Poolable;
16	import com.bumptech.glide.util.pool.StateVerifier;
17	import java.util.ArrayList;
18	import java.util.Iterator;
19	import java.util.List;
20	import java.util.concurrent.Executor;
21	import java.util.concurrent.atomic.AtomicInteger;
22	
23	/**
24	 * A class that manages a load by adding and removing callbacks for for the load and notifying
25	 * callbacks when the load completes.
26	 */
27	class EngineJob<R> implements DecodeJob.Callback<R>, Poolable {
28	  private static final EngineResourceFactory DEFAULT_FACTORY = new EngineResourceFactory();
29	
30	  @SuppressWarnings("WeakerAccess")
31	  @Synthetic
32	  final ResourceCallbacksAndExecutors cbs = new ResourceCallbacksAndExecutors();
33	
34	  private final StateVerifier stateVerifier = StateVerifier.newInstance();
35	  private final ResourceListener resourceListener;
36	  private final Pools.Pool<EngineJob<?>> pool;
37	  private final EngineResourceFactory engineResourceFactory;
38	  private final EngineJobListener engineJobListener;
39	  private final GlideExecutor diskCacheExecutor;
40	  private final GlideExecutor sourceExecutor;
41	  private final GlideExecutor sourceUnlimitedExecutor;
42	  private final GlideExecutor animationExecutor;
43	  private final AtomicInteger pendingCallbacks = new AtomicInteger();
44	
45	  private Key key;
46	  private boolean isCacheable;
47	  private boolean useUnlimitedSourceGeneratorPool;
48	  private boolean useAnimationPool;
49	  private boolean onlyRetrieveFromCache;
50	  private Resource<?> resource;
51	
52	  @SuppressWarnings("WeakerAccess")
53	  @Synthetic
54	  DataSource dataSource;
55	
56	  private boolean hasResource;
57	
58	  @SuppressWarnings("WeakerAccess")
59	  @Synthetic
60	  GlideException exception;
61	
62	  private boolean hasLoadFailed;
63	
64	  @SuppressWarnings("WeakerAccess")
65	  @Synthetic
66	  EngineResource<?> engineResource;
67	
68	  private DecodeJob<R> decodeJob;
69	
70	  // Checked primarily on the main thread, but also on other threads in reschedule.
71	  private volatile boolean isCancelled;
72	  private boolean isLoadedFromAlternateCacheKey;
73	
74	  EngineJob(
75	      GlideExecutor diskCacheExecutor,
76	      GlideExecutor sourceExecutor,
77	      GlideExecutor sourceUnlimitedExecutor,
78	      GlideExecutor animationExecutor,
79	      EngineJobListener engineJobListener,
80	      ResourceListener resourceListener,
81	      Pools.Pool<EngineJob<?>> pool) {
82	    this(
83	        diskCacheExecutor,
84	        sourceExecutor,
85	        sourceUnlimitedExecutor,
86	        animationExecutor,
87	        engineJobListener,
88	        resourceListener,
89	        pool,
90	        DEFAULT_FACTORY);
91	  }
92	
93	  @VisibleForTesting
94	  EngineJob(
95	      GlideExecutor diskCacheExecutor,
96	      GlideExecutor sourceExecutor,
97	      GlideExecutor sourceUnlimitedExecutor,
98	      GlideExecutor animationExecutor,
99	      EngineJobListener engineJobListener,
100	      ResourceListener resourceListener,
101	      Pools.Pool<EngineJob<?>> pool,
102	      EngineResourceFactory engineResourceFactory) {
103	    this.diskCacheExecutor = diskCacheExecutor;
104	    this.sourceExecutor = sourceExecutor;
105	    this.sourceUnlimitedExecutor = sourceUnlimitedExecutor;
106	    this.animationExecutor = animationExecutor;
107	    this.engineJobListener = engineJobListener;
108	    this.resourceListener = resourceListener;
109	    this.pool = pool;
110	    this.engineResourceFactory = engineResourceFactory;
111	  }
112	
113	  @VisibleForTesting
114	  synchronized EngineJob<R> init(
115	      Key key,
116	      boolean isCacheable,
117	      boolean useUnlimitedSourceGeneratorPool,
118	      boolean useAnimationPool,
119	      boolean onlyRetrieveFromCache) {
120	    this.key = key;
121	    this.isCacheable = isCacheable;
122	    this.useUnlimitedSourceGeneratorPool = useUnlimitedSourceGeneratorPool;
123	    this.useAnimationPool = useAnimationPool;
124	    this.onlyRetrieveFromCache = onlyRetrieveFromCache;
125	    return this;
126	  }
127	
128	  public synchronized void start(DecodeJob<R> decodeJob) {
129	    this.decodeJob = decodeJob;
130	    GlideExecutor executor =
131	        decodeJob.willDecodeFromCache() ? diskCacheExecutor : getActiveSourceExecutor();
132	    executor.execute(decodeJob);
133	  }
134	
135	  synchronized void addCallback(final ResourceCallback cb, Executor callbackExecutor) {
136	    stateVerifier.throwIfRecycled();
137	    cbs.add(cb, callbackExecutor);
138	    if (hasResource) {
139	      // Acquire early so that the resource isn't recycled while the Runnable below is still sitting
140	      // in the executors queue.
141	      incrementPendingCallbacks(1);
142	      callbackExecutor.execute(new CallResourceReady(cb));
143	    } else if (hasLoadFailed) {
144	      incrementPendingCallbacks(1);
145	      callbackExecutor.execute(new CallLoadFailed(cb));
146	    } else {
147	      Preconditions.checkArgument(!isCancelled, "Cannot add callbacks to a cancelled EngineJob");
148	    }
149	  }
150	
151	  @SuppressWarnings("WeakerAccess")
152	  @Synthetic
153	  @GuardedBy("this")
154	  void callCallbackOnResourceReady(ResourceCallback cb) {
155	    try {
156	      // This is overly broad, some Glide code is actually called here, but it's much
157	      // simpler to encapsulate here than to do so at the actual call point in the
158	      // Request implementation.
159	      cb.onResourceReady(engineResource, dataSource, isLoadedFromAlternateCacheKey);
160	    } catch (Throwable t) {
161	      throw new CallbackException(t);
162	    }
163	  }
164	
165	  @SuppressWarnings("WeakerAccess")
166	  @Synthetic
167	  @GuardedBy("this")
168	  void callCallbackOnLoadFailed(ResourceCallback cb) {
169	    // This is overly broad, some Glide code is actually called here, but it's much
170	    // simpler to encapsulate here than to do so at the actual call point in the Request
171	    // implementation.
172	    try {
173	      cb.onLoadFailed(exception);
174	    } catch (Throwable t) {
175	      throw new CallbackException(t);
176	    }
177	  }
178	
179	  synchronized void removeCallback(ResourceCallback cb) {
180	    stateVerifier.throwIfRecycled();
181	    cbs.remove(cb);
182	    if (cbs.isEmpty()) {
183	      cancel();
184	      boolean isFinishedRunning = hasResource || hasLoadFailed;
185	      if (isFinishedRunning && pendingCallbacks.get() == 0) {
186	        release();
187	      }
188	    }
189	  }
190	
191	  boolean onlyRetrieveFromCache() {
192	    return onlyRetrieveFromCache;
193	  }
194	
195	  private GlideExecutor getActiveSourceExecutor() {
196	    return useUnlimitedSourceGeneratorPool
197	        ? sourceUnlimitedExecutor
198	        : (useAnimationPool ? animationExecutor : sourceExecutor);
199	  }
200	
201	  // Exposed for testing.
202	  void cancel() {
203	    if (isDone()) {
204	      return;
205	    }
206	
207	    isCancelled = true;
208	    decodeJob.cancel();
209	    engineJobListener.onEngineJobCancelled(this, key);
210	  }
211	
212	  // Exposed for testing.
213	  synchronized boolean isCancelled() {
214	    return isCancelled;
215	  }
216	
217	  private boolean isDone() {
218	    return hasLoadFailed || hasResource || isCancelled;
219	  }
220	
221	  // We have to post Runnables in a loop. Typically there will be very few callbacks. AccessorMethod
222	  // seems to be a false positive
223	  @SuppressWarnings({
224	    "WeakerAccess",
225	    "PMD.AvoidInstantiatingObjectsInLoops",
226	    "PMD.AccessorMethodGeneration"
227	  })
228	  @Synthetic
229	  void notifyCallbacksOfResult() {
230	    ResourceCallbacksAndExecutors copy;
231	    Key localKey;
232	    EngineResource<?> localResource;
233	    synchronized (this) {
234	      stateVerifier.throwIfRecycled();
235	      if (isCancelled) {
236	        // TODO: Seems like we might as well put this in the memory cache instead of just recycling
237	        // it since we've gotten this far...
238	        resource.recycle();
239	        release();
240	        return;
241	      } else if (cbs.isEmpty()) {
242	        throw new IllegalStateException("Received a resource without any callbacks to notify");
243	      } else if (hasResource) {
244	        throw new IllegalStateException("Already have resource");
245	      }
246	      engineResource = engineResourceFactory.build(resource, isCacheable, key, resourceListener);
247	      // Hold on to resource for duration of our callbacks below so we don't recycle it in the
248	      // middle of notifying if it synchronously released by one of the callbacks. Acquire it under
249	      // a lock here so that any newly added callback that executes before the next locked section
250	      // below can't recycle the resource before we call the callbacks.
251	      hasResource = true;
252	      copy = cbs.copy();
253	      incrementPendingCallbacks(copy.size() + 1);
254	
255	      localKey = key;
256	      localResource = engineResource;
257	    }
258	
259	    engineJobListener.onEngineJobComplete(this, localKey, localResource);
260	
261	    for (final ResourceCallbackAndExecutor entry : copy) {
262	      entry.executor.execute(new CallResourceReady(entry.cb));
263	    }
264	    decrementPendingCallbacks();
265	  }
266	
267	  @SuppressWarnings("WeakerAccess")
268	  @Synthetic
269	  synchronized void incrementPendingCallbacks(int count) {
270	    Preconditions.checkArgument(isDone(), "Not yet complete!");
271	    if (pendingCallbacks.getAndAdd(count) == 0 && engineResource != null) {
272	      engineResource.acquire();
273	    }
274	  }
275	
276	  @SuppressWarnings("WeakerAccess")
277	  @Synthetic
278	  void decrementPendingCallbacks() {
279	    EngineResource<?> toRelease = null;
280	    synchronized (this) {
281	      stateVerifier.throwIfRecycled();
282	      Preconditions.checkArgument(isDone(), "Not yet complete!");
283	      int decremented = pendingCallbacks.decrementAndGet();
284	      Preconditions.checkArgument(decremented >= 0, "Can't decrement below 0");
285	      if (decremented == 0) {
286	        toRelease = engineResource;
287	
288	        release();
289	      }
290	    }
291	
292	    if (toRelease != null) {
293	      toRelease.release();
294	    }
295	  }
296	
297	  private synchronized void release() {
298	    if (key == null) {
299	      throw new IllegalArgumentException();
300	    }
301	    cbs.clear();
302	    key = null;
303	    engineResource = null;
304	    resource = null;
305	    hasLoadFailed = false;
306	    isCancelled = false;
307	    hasResource = false;
308	    isLoadedFromAlternateCacheKey = false;
309	    decodeJob.release(/* isRemovedFromQueue= */ false);
310	    decodeJob = null;
311	    exception = null;
312	    dataSource = null;
313	    pool.release(this);
314	  }
315	
316	  @Override
317	  public void onResourceReady(
318	      Resource<R> resource, DataSource dataSource, boolean isLoadedFromAlternateCacheKey) {
319	    synchronized (this) {
320	      this.resource = resource;
321	      this.dataSource = dataSource;
322	      this.isLoadedFromAlternateCacheKey = isLoadedFromAlternateCacheKey;
323	    }
324	    notifyCallbacksOfResult();
325	  }
326	
327	  @Override
328	  public void onLoadFailed(GlideException e) {
329	    synchronized (this) {
330	      this.exception = e;
331	    }
332	    notifyCallbacksOfException();
333	  }
334	
335	  @Override
336	  public void reschedule(DecodeJob<?> job) {
337	    // Even if the job is cancelled here, it still needs to be scheduled so that it can clean itself
338	    // up.
339	    getActiveSourceExecutor().execute(job);
340	  }
341	
342	  // We have to post Runnables in a loop. Typically there will be very few callbacks. Acessor method
343	  // warning seems to be false positive.
344	  @SuppressWarnings({
345	    "WeakerAccess",
346	    "PMD.AvoidInstantiatingObjectsInLoops",
347	    "PMD.AccessorMethodGeneration"
348	  })
349	  @Synthetic
350	  void notifyCallbacksOfException() {
351	    ResourceCallbacksAndExecutors copy;
352	    Key localKey;
353	    synchronized (this) {
354	      stateVerifier.throwIfRecycled();
355	      if (isCancelled) {
356	        release();
357	        return;
358	      } else if (cbs.isEmpty()) {
359	        throw new IllegalStateException("Received an exception without any callbacks to notify");
360	      } else if (hasLoadFailed) {
361	        throw new IllegalStateException("Already failed once");
362	      }
363	      hasLoadFailed = true;
364	
365	      localKey = key;
366	
367	      copy = cbs.copy();
368	      // One for each callback below, plus one for ourselves so that we finish if a callback runs on
369	      // another thread before we finish scheduling all of them.
370	      incrementPendingCallbacks(copy.size() + 1);
371	    }
372	
373	    engineJobListener.onEngineJobComplete(this, localKey, /* resource= */ null);
374	
375	    for (ResourceCallbackAndExecutor entry : copy) {
376	      entry.executor.execute(new CallLoadFailed(entry.cb));
377	    }
378	    decrementPendingCallbacks();
379	  }
380	
381	  @NonNull
382	  @Override
383	  public StateVerifier getVerifier() {
384	    return stateVerifier;
385	  }
386	
387	  private class CallLoadFailed implements Runnable {
388	
389	    private final ResourceCallback cb;
390	
391	    CallLoadFailed(ResourceCallback cb) {
392	      this.cb = cb;
393	    }
394	
395	    @Override
396	    public void run() {
397	      // Make sure we always acquire the request lock, then the EngineJob lock to avoid deadlock
398	      // (b/136032534).
399	      synchronized (cb.getLock()) {
400	        synchronized (EngineJob.this) {
401	          if (cbs.contains(cb)) {
402	            callCallbackOnLoadFailed(cb);
403	          }
404	
405	          decrementPendingCallbacks();
406	        }
407	      }
408	    }
409	  }
410	
411	  private class CallResourceReady implements Runnable {
412	
413	    private final ResourceCallback cb;
414	
415	    CallResourceReady(ResourceCallback cb) {
416	      this.cb = cb;
417	    }
418	
419	    @Override
420	    public void run() {
421	      // Make sure we always acquire the request lock, then the EngineJob lock to avoid deadlock
422	      // (b/136032534).
423	      synchronized (cb.getLock()) {
424	        synchronized (EngineJob.this) {
425	          if (cbs.contains(cb)) {
426	            // Acquire for this particular callback.
427	            engineResource.acquire();
428	            callCallbackOnResourceReady(cb);
429	            removeCallback(cb);
430	          }
431	          decrementPendingCallbacks();
432	        }
433	      }
434	    }
435	  }
436	
437	  static final class ResourceCallbacksAndExecutors
438	      implements Iterable<ResourceCallbackAndExecutor> {
439	    private final List<ResourceCallbackAndExecutor> callbacksAndExecutors;
440	
441	    ResourceCallbacksAndExecutors() {
442	      this(new ArrayList<ResourceCallbackAndExecutor>(2));
443	    }
444	
445	    ResourceCallbacksAndExecutors(List<ResourceCallbackAndExecutor> callbacksAndExecutors) {
446	      this.callbacksAndExecutors = callbacksAndExecutors;
447	    }
448	
449	    void add(ResourceCallback cb, Executor executor) {
450	      callbacksAndExecutors.add(new ResourceCallbackAndExecutor(cb, executor));
451	    }
452	
453	    void remove(ResourceCallback cb) {
454	      callbacksAndExecutors.remove(defaultCallbackAndExecutor(cb));
455	    }
456	
457	    boolean contains(ResourceCallback cb) {
458	      return callbacksAndExecutors.contains(defaultCallbackAndExecutor(cb));
459	    }
460	
461	    boolean isEmpty() {
462	      return callbacksAndExecutors.isEmpty();
463	    }
464	
465	    int size() {
466	      return callbacksAndExecutors.size();
467	    }
468	
469	    void clear() {
470	      callbacksAndExecutors.clear();
471	    }
472	
473	    ResourceCallbacksAndExecutors copy() {
474	      return new ResourceCallbacksAndExecutors(new ArrayList<>(callbacksAndExecutors));
475	    }
476	
477	    private static ResourceCallbackAndExecutor defaultCallbackAndExecutor(ResourceCallback cb) {
478	      return new ResourceCallbackAndExecutor(cb, Executors.directExecutor());
479	    }
480	
481	    @NonNull
482	    @Override
483	    public Iterator<ResourceCallbackAndExecutor> iterator() {
484	      return callbacksAndExecutors.iterator();
485	    }
486	  }
487	
488	  static final class ResourceCallbackAndExecutor {
489	    final ResourceCallback cb;
490	    final Executor executor;
491	
492	    ResourceCallbackAndExecutor(ResourceCallback cb, Executor executor) {
493	      this.cb = cb;
494	      this.executor = executor;
495	    }
496	
497	    @Override
498	    public boolean equals(Object o) {
499	      if (o instanceof ResourceCallbackAndExecutor) {
500	        ResourceCallbackAndExecutor other = (ResourceCallbackAndExecutor) o;
501	        return cb.equals(other.cb);
502	      }
503	      return false;
504	    }
505	
506	    @Override
507	    public int hashCode() {
508	      return cb.hashCode();
509	    }
510	  }
511	
512	  @VisibleForTesting
513	  static class EngineResourceFactory {
514	    public <R> EngineResource<R> build(
515	        Resource<R> resource, boolean isMemoryCacheable, Key key, ResourceListener listener) {
516	      return new EngineResource<>(
517	          resource, isMemoryCacheable, /* isRecyclable= */ true, key, listener);
518	    }
519	  }
520	}
