541	  /** A callback method that should never be invoked directly. */
542	  @SuppressWarnings("unchecked")
543	  @Override
544	  public void onResourceReady(
545	      Resource<?> resource, DataSource dataSource, boolean isLoadedFromAlternateCacheKey) {
546	    stateVerifier.throwIfRecycled();
547	    Resource<?> toRelease = null;
548	    try {
549	      synchronized (requestLock) {
550	        loadStatus = null;
551	        if (resource == null) {
552	          GlideException exception =
553	              new GlideException(
554	                  "Expected to receive a Resource<R> with an "
555	                      + "object of "
556	                      + transcodeClass
557	                      + " inside, but instead got null.");
558	          onLoadFailed(exception);
559	          return;
560	        }
561	
562	        Object received = resource.get();
563	        if (received == null || !transcodeClass.isAssignableFrom(received.getClass())) {
564	          toRelease = resource;
565	          this.resource = null;
566	          GlideException exception =
567	              new GlideException(
568	                  "Expected to receive an object of "
569	                      + transcodeClass
570	                      + " but instead"
571	                      + " got "
572	                      + (received != null ? received.getClass() : "")
573	                      + "{"
574	                      + received
575	                      + "} inside"
576	                      + " "
577	                      + "Resource{"
578	                      + resource
579	                      + "}."
580	                      + (received != null
581	                          ? ""
582	                          : " "
583	                              + "To indicate failure return a null Resource "
584	                              + "object, rather than a Resource object containing null data."));
585	          onLoadFailed(exception);
586	          return;
587	        }
588	
589	        if (!canSetResource()) {
590	          toRelease = resource;
591	          this.resource = null;
592	          // We can't put the status to complete before asking canSetResource().
593	          status = Status.COMPLETE;
594	          GlideTrace.endSectionAsync(TAG, cookie);
595	          return;
596	        }
597	
598	        onResourceReady(
599	            (Resource<R>) resource, (R) received, dataSource, isLoadedFromAlternateCacheKey);
600	      }
601	    } finally {
602	      if (toRelease != null) {
603	        engine.release(toRelease);
604	      }
605	    }
606	  }
