690	  private void onLoadFailed(GlideException e, int maxLogLevel) {
691	    stateVerifier.throwIfRecycled();
692	    synchronized (requestLock) {
693	      e.setOrigin(requestOrigin);
694	      int logLevel = glideContext.getLogLevel();
695	      if (logLevel <= maxLogLevel) {
696	        Log.w(
697	            GLIDE_TAG,
698	            "Load failed for [" + model + "] with dimensions [" + width + "x" + height + "]",
699	            e);
700	        if (logLevel <= Log.INFO) {
701	          e.logRootCauses(GLIDE_TAG);
702	        }
703	      }
704	
705	      loadStatus = null;
706	      status = Status.FAILED;
707	
708	      notifyRequestCoordinatorLoadFailed();
709	
710	      isCallingCallbacks = true;
711	      try {
712	        // TODO: what if this is a thumbnail request?
713	        boolean anyListenerHandledUpdatingTarget = false;
714	        if (requestListeners != null) {
715	          for (RequestListener<R> listener : requestListeners) {
716	            anyListenerHandledUpdatingTarget |=
717	                listener.onLoadFailed(e, model, target, isFirstReadyResource());
718	          }
719	        }
720	        anyListenerHandledUpdatingTarget |=
721	            targetListener != null
722	                && targetListener.onLoadFailed(e, model, target, isFirstReadyResource());
723	
724	        if (!anyListenerHandledUpdatingTarget) {
725	          setErrorPlaceholder();
726	        }
727	      } finally {
728	        isCallingCallbacks = false;
729	      }
730	
731	      GlideTrace.endSectionAsync(TAG, cookie);
732	    }
733	  }
