33	public class BitmapEncoder implements ResourceEncoder<Bitmap> {
34	  /**
35	   * An integer option between 0 and 100 that is used as the compression quality.
36	   *
37	   * <p>Defaults to 90.
38	   */
39	  public static final Option<Integer> COMPRESSION_QUALITY =
40	      Option.memory("com.bumptech.glide.load.resource.bitmap.BitmapEncoder.CompressionQuality", 90);
41	
42	  /**
43	   * An {@link android.graphics.Bitmap.CompressFormat} option used as the format to encode the
44	   * {@link android.graphics.Bitmap}.
45	   *
46	   * <p>Defaults to {@link android.graphics.Bitmap.CompressFormat#JPEG} for images without alpha and
47	   * {@link android.graphics.Bitmap.CompressFormat#PNG} for images with alpha.
48	   */
49	  public static final Option<Bitmap.CompressFormat> COMPRESSION_FORMAT =
50	      Option.memory("com.bumptech.glide.load.resource.bitmap.BitmapEncoder.CompressionFormat");
51	
52	  private static final String TAG = "BitmapEncoder";
53	  @Nullable private final ArrayPool arrayPool;
54	
55	  public BitmapEncoder(@NonNull ArrayPool arrayPool) {
56	    this.arrayPool = arrayPool;
57	  }
58	
59	  /**
60	   * @deprecated Use {@link #BitmapEncoder(ArrayPool)} instead.
61	   */
62	  @Deprecated
63	  public BitmapEncoder() {
64	    arrayPool = null;
65	  }
66	
67	  @Override
68	  public boolean encode(
69	      @NonNull Resource<Bitmap> resource, @NonNull File file, @NonNull Options options) {
70	    final Bitmap bitmap = resource.get();
71	    Bitmap.CompressFormat format = getFormat(bitmap, options);
72	    GlideTrace.beginSectionFormat(
73	        "encode: [%dx%d] %s", bitmap.getWidth(), bitmap.getHeight(), format);
74	    try {
75	      long start = LogTime.getLogTime();
76	      int quality = options.get(COMPRESSION_QUALITY);
77	
78	      boolean success = false;
79	      OutputStream os = null;
80	      try {
81	        os = new FileOutputStream(file);
82	        if (arrayPool != null) {
83	          os = new BufferedOutputStream(os, arrayPool);
84	        }
85	        bitmap.compress(format, quality, os);
86	        os.close();
87	        success = true;
88	      } catch (IOException e) {
89	        if (Log.isLoggable(TAG, Log.DEBUG)) {
90	          Log.d(TAG, "Failed to encode Bitmap", e);
91	        }
92	      } finally {
93	        if (os != null) {
94	          try {
95	            os.close();
96	          } catch (IOException e) {
97	            // Do nothing.
98	          }
99	        }
100	      }
101	
102	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
103	        Log.v(
104	            TAG,
105	            "Compressed with type: "
106	                + format
107	                + " of size "
108	                + Util.getBitmapByteSize(bitmap)
109	                + " in "
110	                + LogTime.getElapsedMillis(start)
111	                + ", options format: "
112	                + options.get(COMPRESSION_FORMAT)
113	                + ", hasAlpha: "
114	                + bitmap.hasAlpha());
115	      }
116	      return success;
117	    } finally {
118	      GlideTrace.endSection();
119	    }
120	  }
121	
122	  private Bitmap.CompressFormat getFormat(Bitmap bitmap, Options options) {
123	    Bitmap.CompressFormat format = options.get(COMPRESSION_FORMAT);
124	    if (format != null) {
125	      return format;
126	    } else if (bitmap.hasAlpha()) {
127	      return Bitmap.CompressFormat.PNG;
128	    } else {
129	      return Bitmap.CompressFormat.JPEG;
130	    }
131	  }
132	
133	  @NonNull
134	  @Override
135	  public EncodeStrategy getEncodeStrategy(@NonNull Options options) {
136	    return EncodeStrategy.TRANSFORMED;
137	  }
138	}
