171	  @Override
172	  public Resource<Bitmap> decode(
173	      @NonNull T resource, int outWidth, int outHeight, @NonNull Options options)
174	      throws IOException {
175	    long frameTimeMicros = options.get(TARGET_FRAME);
176	    if (frameTimeMicros < 0 && frameTimeMicros != DEFAULT_FRAME) {
177	      throw new IllegalArgumentException(
178	          "Requested frame must be non-negative, or DEFAULT_FRAME, given: " + frameTimeMicros);
179	    }
180	    Integer frameOption = options.get(FRAME_OPTION);
181	    if (frameOption == null) {
182	      frameOption = DEFAULT_FRAME_OPTION;
183	    }
184	    DownsampleStrategy downsampleStrategy = options.get(DownsampleStrategy.OPTION);
185	    if (downsampleStrategy == null) {
186	      downsampleStrategy = DownsampleStrategy.DEFAULT;
187	    }
188	
189	    final Bitmap result;
190	    MediaMetadataRetriever mediaMetadataRetriever = factory.build();
191	    try {
192	      initializer.initializeRetriever(mediaMetadataRetriever, resource);
193	      result =
194	          decodeFrame(
195	              resource,
196	              mediaMetadataRetriever,
197	              frameTimeMicros,
198	              frameOption,
199	              outWidth,
200	              outHeight,
201	              downsampleStrategy);
202	    } finally {
203	      if (Build.VERSION.SDK_INT >= VERSION_CODES.Q) {
204	        mediaMetadataRetriever.close();
205	      } else {
206	        mediaMetadataRetriever.release();
207	      }
208	    }
209	
210	    return BitmapResource.obtain(result, bitmapPool);
211	  }
