213	  @Nullable
214	  private Bitmap decodeFrame(
215	      @NonNull T resource,
216	      MediaMetadataRetriever mediaMetadataRetriever,
217	      long frameTimeMicros,
218	      int frameOption,
219	      int outWidth,
220	      int outHeight,
221	      DownsampleStrategy strategy) {
222	    if (isUnsupportedFormat(resource, mediaMetadataRetriever)) {
223	      throw new IllegalStateException("Cannot decode VP8 video on CrOS.");
224	    }
225	
226	    Bitmap result = null;
227	    // Arguably we should handle the case where just width or just height is set to
228	    // Target.SIZE_ORIGINAL. Up to and including OMR1, MediaMetadataRetriever defaults to setting
229	    // the dimensions to the display width and height if they aren't specified (ie
230	    // getScaledFrameAtTime is not used). Given that this is an optimization only if
231	    // Target.SIZE_ORIGINAL is not used and not using getScaledFrameAtTime ever would match the
232	    // behavior of Glide in all versions of Android prior to OMR1, it's probably fine for now.
233	    if (Build.VERSION.SDK_INT >= VERSION_CODES.O_MR1
234	        && outWidth != Target.SIZE_ORIGINAL
235	        && outHeight != Target.SIZE_ORIGINAL
236	        && strategy != DownsampleStrategy.NONE) {
237	      result =
238	          decodeScaledFrame(
239	              mediaMetadataRetriever, frameTimeMicros, frameOption, outWidth, outHeight, strategy);
240	    }
241	
242	    if (result == null) {
243	      result = decodeOriginalFrame(mediaMetadataRetriever, frameTimeMicros, frameOption);
244	    }
245	
246	    // MediaMetadataRetriever has a bug where HDR videos with 180 deg rotations are rotated twice,
247	    // causing the output frame to appear upside. This needs to be corrected for all versions of
248	    // Android until a platform fix lands.
249	    result = correctHdr180DegVideoFrameOrientation(mediaMetadataRetriever, result);
250	
251	    // Throwing an exception works better in our error logging than returning null. It shouldn't
252	    // be expensive because video decoders are attempted after image loads. Video errors are often
253	    // logged by the framework, so we can also use this error to suggest callers look for the
254	    // appropriate tags in adb.
255	    if (result == null) {
256	      throw new VideoDecoderException();
257	    }
258	
259	    return result;
260	  }
261	
262	  /**
263	   * Corrects the orientation of a bitmap extracted from an HDR video with a 180 degree rotation
264	   * angle.
265	   *
266	   * <p>This method will only return a rotated bitmap instead of the input bitmap if
267	   *
268	   * <ul>
269	   *   <li>The Android SDK level is >= R && < T OR the build id is one of T builds without the
270	   *       platform fix.
271	   *   <li>The video has a color transfer function with an HLG or ST2084 (PQ) transfer function.
272	   *   <li>The video has a color standard of BT.2020.
273	   *   <li>The video has a rotation angle of +/- 180 degrees.
274	   * </ul>
275	   */
276	  @TargetApi(Build.VERSION_CODES.R)
277	  private static Bitmap correctHdr180DegVideoFrameOrientation(
278	      MediaMetadataRetriever mediaMetadataRetriever, Bitmap frame) {
279	    if (!isHdr180RotationFixRequired()) {
280	      return frame;
281	    }
282	    boolean requiresHdr180RotationFix = false;
283	    try {
284	      if (isHDR(mediaMetadataRetriever)) {
285	        String rotationString =
286	            mediaMetadataRetriever.extractMetadata(
287	                MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION);
288	        int rotation = Integer.parseInt(rotationString);
289	        requiresHdr180RotationFix = Math.abs(rotation) == 180;
290	      }
291	    } catch (NumberFormatException e) {
292	      if (Log.isLoggable(TAG, Log.DEBUG)) {
293	        Log.d(TAG, "Exception trying to extract HDR transfer function or rotation");
294	      }
295	    }
296	
297	    if (!requiresHdr180RotationFix) {
298	      return frame;
299	    }
300	
301	    if (Log.isLoggable(TAG, Log.DEBUG)) {
302	      Log.d(TAG, "Applying HDR 180 deg thumbnail correction");
303	    }
304	    Matrix rotationMatrix = new Matrix();
305	    rotationMatrix.postRotate(
306	        /* degrees= */ 180, frame.getWidth() / 2.0f, frame.getHeight() / 2.0f);
307	    return Bitmap.createBitmap(
308	        frame,
309	        /* x= */ 0,
310	        /* y= */ 0,
311	        frame.getWidth(),
312	        frame.getHeight(),
313	        rotationMatrix,
314	        /* filter= */ true);
315	  }
