317	  @RequiresApi(VERSION_CODES.R)
318	  private static boolean isHDR(MediaMetadataRetriever mediaMetadataRetriever)
319	      throws NumberFormatException {
320	    String colorTransferString =
321	        mediaMetadataRetriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_COLOR_TRANSFER);
322	    String colorStandardString =
323	        mediaMetadataRetriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_COLOR_STANDARD);
324	    int colorTransfer = Integer.parseInt(colorTransferString);
325	    int colorStandard = Integer.parseInt(colorStandardString);
326	    // This check needs to match the isHDR check in
327	    // frameworks/av/media/libstagefright/FrameDecoder.cpp.
328	    return (colorTransfer == MediaFormat.COLOR_TRANSFER_HLG
329	            || colorTransfer == MediaFormat.COLOR_TRANSFER_ST2084)
330	        && colorStandard == MediaFormat.COLOR_STANDARD_BT2020;
331	  }
