357	  @Nullable
358	  @TargetApi(Build.VERSION_CODES.O_MR1)
359	  private static Bitmap decodeScaledFrame(
360	      MediaMetadataRetriever mediaMetadataRetriever,
361	      long frameTimeMicros,
362	      int frameOption,
363	      int outWidth,
364	      int outHeight,
365	      DownsampleStrategy strategy) {
366	    try {
367	      int originalWidth =
368	          Integer.parseInt(
369	              mediaMetadataRetriever.extractMetadata(
370	                  MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH));
371	      int originalHeight =
372	          Integer.parseInt(
373	              mediaMetadataRetriever.extractMetadata(
374	                  MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT));
375	      int orientation =
376	          Integer.parseInt(
377	              mediaMetadataRetriever.extractMetadata(
378	                  MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION));
379	
380	      if (orientation == 90 || orientation == 270) {
381	        int temp = originalWidth;
382	        //noinspection SuspiciousNameCombination
383	        originalWidth = originalHeight;
384	        originalHeight = temp;
385	      }
386	
387	      float scaleFactor =
388	          strategy.getScaleFactor(originalWidth, originalHeight, outWidth, outHeight);
389	
390	      int decodeWidth = Math.round(scaleFactor * originalWidth);
391	      int decodeHeight = Math.round(scaleFactor * originalHeight);
392	
393	      return mediaMetadataRetriever.getScaledFrameAtTime(
394	          frameTimeMicros, frameOption, decodeWidth, decodeHeight);
395	    } catch (Throwable t) {
396	      // This is aggressive, but we'd rather catch errors caused by reading and/or parsing metadata
397	      // here and fall back to just decoding the frame whenever possible. If the exception is thrown
398	      // just from decoding the frame, then it will be thrown and exposed to callers by the method
399	      // below.
400	      if (Log.isLoggable(TAG, Log.DEBUG)) {
401	        Log.d(
402	            TAG,
403	            "Exception trying to decode a scaled frame on oreo+, falling back to a fullsize frame",
404	            t);
405	      }
406	
407	      return null;
408	    }
409	  }
410	
411	  private static Bitmap decodeOriginalFrame(
412	      MediaMetadataRetriever mediaMetadataRetriever, long frameTimeMicros, int frameOption) {
413	    return mediaMetadataRetriever.getFrameAtTime(frameTimeMicros, frameOption);
414	  }
