416	  /** Returns true if the format type is unsupported on the device. */
417	  private boolean isUnsupportedFormat(
418	      @NonNull T resource, MediaMetadataRetriever mediaMetadataRetriever) {
419	    // MediaFormat.KEY_MIME check below requires at least JELLY_BEAN
420	    if (Build.VERSION.SDK_INT < VERSION_CODES.JELLY_BEAN) {
421	      return false;
422	    }
423	
424	    // The primary known problem is vp8 video on ChromeOS (ARC) devices.
425	    boolean isArc = Build.DEVICE != null && Build.DEVICE.matches(".+_cheets|cheets_.+");
426	    if (!isArc) {
427	      return false;
428	    }
429	
430	    MediaExtractor mediaExtractor = null;
431	    try {
432	      // Include the MediaMetadataRetriever extract in the try block out of an abundance of caution.
433	      String mimeType =
434	          mediaMetadataRetriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_MIMETYPE);
435	      if (!WEBM_MIME_TYPE.equals(mimeType)) {
436	        return false;
437	      }
438	
439	      // Only construct a MediaExtractor for webm files, since the constructor makes a JNI call
440	      mediaExtractor = new MediaExtractor();
441	      initializer.initializeExtractor(mediaExtractor, resource);
442	      int numTracks = mediaExtractor.getTrackCount();
443	      for (int i = 0; i < numTracks; ++i) {
444	        MediaFormat mediaformat = mediaExtractor.getTrackFormat(i);
445	        String trackMimeType = mediaformat.getString(MediaFormat.KEY_MIME);
446	        if (MediaFormat.MIMETYPE_VIDEO_VP8.equals(trackMimeType)) {
447	          return true;
448	        }
449	      }
450	    } catch (Throwable t) {
451	      // Catching everything here out of an abundance of caution
452	      if (Log.isLoggable(TAG, Log.DEBUG)) {
453	        Log.d(TAG, "Exception trying to extract track info for a webm video on CrOS.", t);
454	      }
455	    } finally {
456	      if (mediaExtractor != null) {
457	        mediaExtractor.release();
458	      }
459	    }
460	
461	    return false;
462	  }
