526	    private MediaDataSource getMediaDataSource(final ByteBuffer data) {
527	      return new MediaDataSource() {
528	        @Override
529	        public int readAt(long position, byte[] buffer, int offset, int size) {
530	          if (position >= data.limit()) {
531	            return -1;
532	          }
533	          data.position((int) position);
534	          int numBytesRead = Math.min(size, data.remaining());
535	          data.get(buffer, offset, numBytesRead);
536	          return numBytesRead;
537	        }
538	
539	        @Override
540	        public long getSize() {
541	          return data.limit();
542	        }
543	
544	        @Override
545	        public void close() {}
546	      };
547	    }
548	  }
