22	/** A DataFetcher that retrieves an {@link java.io.InputStream} for a Url. */
23	public class HttpUrlFetcher implements DataFetcher<InputStream> {
24	  private static final String TAG = "HttpUrlFetcher";
25	  private static final int MAXIMUM_REDIRECTS = 5;
26	  @VisibleForTesting static final String REDIRECT_HEADER_FIELD = "Location";
27	
28	  @VisibleForTesting
29	  static final HttpUrlConnectionFactory DEFAULT_CONNECTION_FACTORY =
30	      new DefaultHttpUrlConnectionFactory();
31	
32	  /** Returned when a connection error prevented us from receiving an http error. */
33	  @VisibleForTesting static final int INVALID_STATUS_CODE = -1;
34	
35	  private final GlideUrl glideUrl;
36	  private final int timeout;
37	  private final HttpUrlConnectionFactory connectionFactory;
38	
39	  private HttpURLConnection urlConnection;
40	  private InputStream stream;
41	  private volatile boolean isCancelled;
