48	  HttpUrlFetcher(GlideUrl glideUrl, int timeout, HttpUrlConnectionFactory connectionFactory) {
49	    this.glideUrl = glideUrl;
50	    this.timeout = timeout;
51	    this.connectionFactory = connectionFactory;
52	  }
