54	  @Override
55	  public void loadData(
56	      @NonNull Priority priority, @NonNull DataCallback<? super InputStream> callback) {
57	    long startTime = LogTime.getLogTime();
58	    try {
59	      InputStream result = loadDataWithRedirects(glideUrl.toURL(), 0, null, glideUrl.getHeaders());
60	      callback.onDataReady(result);
61	    } catch (IOException e) {
62	      if (Log.isLoggable(TAG, Log.DEBUG)) {
63	        Log.d(TAG, "Failed to load data for url", e);
64	      }
65	      callback.onLoadFailed(e);
66	    } finally {
67	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
68	        Log.v(TAG, "Finished http url fetcher fetch in " + LogTime.getElapsedMillis(startTime));
69	      }
70	    }
71	  }
