73	  private InputStream loadDataWithRedirects(
74	      URL url, int redirects, URL lastUrl, Map<String, String> headers) throws HttpException {
75	    if (redirects >= MAXIMUM_REDIRECTS) {
76	      throw new HttpException(
77	          "Too many (> " + MAXIMUM_REDIRECTS + ") redirects!", INVALID_STATUS_CODE);
78	    }
79	    // Comparing the URLs using .equals performs additional network I/O and is generally broken.
80	    // See http://michaelscharf.blogspot.com/2006/11/javaneturlequals-and-hashcode-make.html.
81	    try {
82	      if (lastUrl != null && url.toURI().equals(lastUrl.toURI())) {
83	        throw new HttpException("In re-direct loop", INVALID_STATUS_CODE);
84	      }
85	    } catch (URISyntaxException e) {
86	      // Do nothing, this is best effort.
87	    }
88	
89	    urlConnection = buildAndConfigureConnection(url, headers);
90	
91	    try {
92	      // Connect explicitly to avoid errors in decoders if connection fails.
93	      urlConnection.connect();
94	      // Set the stream so that it's closed in cleanup to avoid resource leaks. See #2352.
95	      stream = urlConnection.getInputStream();
96	    } catch (IOException e) {
97	      throw new HttpException(
98	          "Failed to connect or obtain data", getHttpStatusCodeOrInvalid(urlConnection), e);
99	    }
100	
101	    if (isCancelled) {
102	      return null;
103	    }
104	
105	    final int statusCode = getHttpStatusCodeOrInvalid(urlConnection);
106	    if (isHttpOk(statusCode)) {
107	      return getStreamForSuccessfulRequest(urlConnection);
108	    } else if (isHttpRedirect(statusCode)) {
109	      String redirectUrlString = urlConnection.getHeaderField(REDIRECT_HEADER_FIELD);
110	      if (TextUtils.isEmpty(redirectUrlString)) {
111	        throw new HttpException("Received empty or null redirect url", statusCode);
112	      }
113	      URL redirectUrl;
114	      try {
115	        redirectUrl = new URL(url, redirectUrlString);
116	      } catch (MalformedURLException e) {
117	        throw new HttpException("Bad redirect url: " + redirectUrlString, statusCode, e);
118	      }
119	      // Closing the stream specifically is required to avoid leaking ResponseBodys in addition
120	      // to disconnecting the url connection below. See #2352.
121	      cleanup();
122	      return loadDataWithRedirects(redirectUrl, redirects + 1, url, headers);
123	    } else if (statusCode == INVALID_STATUS_CODE) {
124	      throw new HttpException(statusCode);
125	    } else {
126	      try {
127	        throw new HttpException(urlConnection.getResponseMessage(), statusCode);
128	      } catch (IOException e) {
129	        throw new HttpException("Failed to get a response message", statusCode, e);
130	      }
131	    }
132	  }
