134	  private static int getHttpStatusCodeOrInvalid(HttpURLConnection urlConnection) {
135	    try {
136	      return urlConnection.getResponseCode();
137	    } catch (IOException e) {
138	      if (Log.isLoggable(TAG, Log.DEBUG)) {
139	        Log.d(TAG, "Failed to get a response code", e);
140	      }
141	    }
142	    return INVALID_STATUS_CODE;
143	  }
