145	  private HttpURLConnection buildAndConfigureConnection(URL url, Map<String, String> headers)
146	      throws HttpException {
147	    HttpURLConnection urlConnection;
148	    try {
149	      urlConnection = connectionFactory.build(url);
150	    } catch (IOException e) {
151	      throw new HttpException("URL.openConnection threw", /* statusCode= */ 0, e);
152	    }
153	    for (Map.Entry<String, String> headerEntry : headers.entrySet()) {
154	      urlConnection.addRequestProperty(headerEntry.getKey(), headerEntry.getValue());
155	    }
156	    urlConnection.setConnectTimeout(timeout);
157	    urlConnection.setReadTimeout(timeout);
158	    urlConnection.setUseCaches(false);
159	    urlConnection.setDoInput(true);
160	    // Stop the urlConnection instance of HttpUrlConnection from following redirects so that
161	    // redirects will be handled by recursive calls to this method, loadDataWithRedirects.
162	    urlConnection.setInstanceFollowRedirects(false);
163	    return urlConnection;
164	  }
