176	  private InputStream getStreamForSuccessfulRequest(HttpURLConnection urlConnection)
177	      throws HttpException {
178	    try {
179	      if (TextUtils.isEmpty(urlConnection.getContentEncoding())) {
180	        int contentLength = urlConnection.getContentLength();
181	        stream = ContentLengthInputStream.obtain(urlConnection.getInputStream(), contentLength);
182	      } else {
183	        if (Log.isLoggable(TAG, Log.DEBUG)) {
