11	import com.bumptech.glide.util.MarkEnforcingInputStream;
12	import java.io.IOException;
13	import java.io.InputStream;
14	
15	/**
16	 * Decodes {@link android.graphics.Bitmap Bitmaps} from {@link java.io.InputStream InputStreams}.
17	 */
18	public class StreamBitmapDecoder implements ResourceDecoder<InputStream, Bitmap> {
19	
20	  private final Downsampler downsampler;
21	  private final ArrayPool byteArrayPool;
22	
23	  public StreamBitmapDecoder(Downsampler downsampler, ArrayPool byteArrayPool) {
24	    this.downsampler = downsampler;
25	    this.byteArrayPool = byteArrayPool;
26	  }
27	
28	  @Override
29	  public boolean handles(@NonNull InputStream source, @NonNull Options options) {
30	    return downsampler.handles(source);
31	  }
32	
33	  @Override
34	  public Resource<Bitmap> decode(
35	      @NonNull InputStream source, int width, int height, @NonNull Options options)
36	      throws IOException {
37	
38	    // Use to fix the mark limit to avoid allocating buffers that fit entire images.
39	    final RecyclableBufferedInputStream bufferedStream;
40	    final boolean ownsBufferedStream;
41	    if (source instanceof RecyclableBufferedInputStream) {
42	      bufferedStream = (RecyclableBufferedInputStream) source;
43	      ownsBufferedStream = false;
44	    } else {
45	      bufferedStream = new RecyclableBufferedInputStream(source, byteArrayPool);
46	      ownsBufferedStream = true;
47	    }
48	
49	    // Use to retrieve exceptions thrown while reading.
50	    // TODO(#126): when the framework no longer returns partially decoded Bitmaps or provides a
51	    // way to determine if a Bitmap is partially decoded, consider removing.
52	    ExceptionPassthroughInputStream exceptionStream =
53	        ExceptionPassthroughInputStream.obtain(bufferedStream);
54	
55	    // Use to read data.
56	    // Ensures that we can always reset after reading an image header so that we can still
57	    // attempt to decode the full image even when the header decode fails and/or overflows our read
58	    // buffer. See #283.
59	    MarkEnforcingInputStream invalidatingStream = new MarkEnforcingInputStream(exceptionStream);
60	    UntrustedCallbacks callbacks = new UntrustedCallbacks(bufferedStream, exceptionStream);
61	    try {
62	      return downsampler.decode(invalidatingStream, width, height, options, callbacks);
63	    } finally {
64	      exceptionStream.release();
65	      if (ownsBufferedStream) {
66	        bufferedStream.release();
67	      }
68	    }
69	  }
70	
71	  /**
72	   * Callbacks that provide reasonable handling for streams that may be unbuffered or insufficiently
73	   * buffered or that may throw exceptions during decoding.
74	   */
75	  static class UntrustedCallbacks implements Downsampler.DecodeCallbacks {
76	    private final RecyclableBufferedInputStream bufferedStream;
77	    private final ExceptionPassthroughInputStream exceptionStream;
78	
79	    UntrustedCallbacks(
80	        RecyclableBufferedInputStream bufferedStream,
81	        ExceptionPassthroughInputStream exceptionStream) {
82	      this.bufferedStream = bufferedStream;
83	      this.exceptionStream = exceptionStream;
84	    }
85	
86	    @Override
87	    public void onObtainBounds() {
88	      // Once we've read the image header, we no longer need to allow the buffer to expand in
89	      // size. To avoid unnecessary allocations reading image data, we fix the mark limit so that it
90	      // is no larger than our current buffer size here. See issue #225.
91	      bufferedStream.fixMarkLimit();
92	    }
93	
94	    @Override
95	    public void onDecodeComplete(BitmapPool bitmapPool, Bitmap downsampled) throws IOException {
96	      // BitmapFactory swallows exceptions during decodes and in some cases when inBitmap is non
97	      // null, may catch and log a stack trace but still return a non null bitmap. To avoid
98	      // displaying partially decoded bitmaps, we catch exceptions reading from the stream in our
99	      // ExceptionCatchingInputStream and throw them here.
100	      IOException streamException = exceptionStream.getException();
101	      if (streamException != null) {
102	        if (downsampled != null) {
103	          bitmapPool.put(downsampled);
104	        }
105	        throw streamException;
106	      }
107	    }
108	  }
109	}
