28	      lifecycleListener.onStart();
29	    }
30	  }
31	
32	  @OnLifecycleEvent(Event.ON_STOP)
33	  public void onStop(@NonNull LifecycleOwner owner) {
34	    for (LifecycleListener lifecycleListener : Util.getSnapshot(lifecycleListeners)) {
35	      lifecycleListener.onStop();
36	    }
37	  }
38	
39	  @OnLifecycleEvent(Event.ON_DESTROY)
40	  public void onDestroy(@NonNull LifecycleOwner owner) {
41	    for (LifecycleListener lifecycleListener : Util.getSnapshot(lifecycleListeners)) {
42	      lifecycleListener.onDestroy();
43	    }
44	    owner.getLifecycle().removeObserver(this);
