51	    if (lifecycle.getCurrentState() == State.DESTROYED) {
52	      listener.onDestroy();
53	    } else if (lifecycle.getCurrentState().isAtLeast(State.STARTED)) {
54	      listener.onStart();
55	    } else {
56	      listener.onStop();
57	    }
58	  }
