  // warning seems to be false positive.
  @SuppressWarnings({
    "WeakerAccess",
    "PMD.AvoidInstantiatingObjectsInLoops",
    "PMD.AccessorMethodGeneration"
  })
  @Synthetic
  void notifyCallbacksOfException() {
